d27bf02f-ab99-43bc-a836-3831f6325e82	4	evolution_gen_4	import numpy as np\nimport re\nimport math\nimport pandas as pd\n\n# --- Helper Functions for Technical Indicators ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        if len(data_arr) >= period:\n            ema_values[0] = np.mean(data_arr[:period])\n            multiplier = 2 / (period + 1)\n            for i in range(1, len(ema_values)):\n                ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period: \n        return None, None, None\n    \n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    \n    if len(short_ema_series) == 0 or len(long_ema_series) == 0:\n        return None, None, None\n\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    \n    if len(macd_line) < signal_period: \n        return macd_line, None, None\n        \n    signal_line = calculate_ema_series(macd_line, signal_period)\n    \n    if len(signal_line) == 0:\n        return macd_line, None, None\n\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    \n    return macd_line, signal_line, histogram\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    \n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    \n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        \n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n        \n    if avg_loss == 0:\n        return 100.0 # No losses, RSI is 100\n    \n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr)) \n    \n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    if prices[-1 - period] == 0: \n        return 0.0\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef calculate_bollinger_bands(prices, period=20, std_dev=2):\n    """Calculates Bollinger Bands."""\n    if len(prices) < period:\n        return None, None\n    sma = calculate_sma(prices, period)\n    std = np.std(prices[-period:])\n    upper_band = sma + std_dev * std\n    lower_band = sma - std_dev * std\n    return upper_band, lower_band\n\ndef calculate_stochastic_oscillator(prices, period=14):\n    """Calculates the Stochastic Oscillator."""\n    if len(prices) < period:\n        return None\n    lowest_low = np