e_stop_loss_factor = 0.88 \n    if is_extreme_volatility: \n        stop_loss_factor = 0.80 \n    elif is_high_volatility:\n        stop_loss_factor = 0.85 \n    else:\n        stop_loss_factor = base_stop_loss_factor\n\n    if current_price < (donchian_high_30 * stop_loss_factor): \n        return "SELL"\n\n    is_primary_downtrend = current_price < sma_50\n    is_momentum_confirming_down = macd_histogram < 0 and prev_macd_histogram >= 0\n    is_sentiment_permissive_for_sell = sentiment_score < 3.0\n    if is_primary_downtrend and is_momentum_confirming_down and is_sentiment_permissive_for_sell:\n        return "SELL"\n\n    is_momentum_fading = macd_hist_delta < 0\n    is_extremely_overbought = rsi > 82\n    if is_extremely_overbought and is_momentum_fading:\n        return "SELL"\n\n    is_primary_uptrend = current_price > sma_50\n    is_momentum_confirming_up = macd_histogram > 0 and prev_macd_histogram <= 0\n    is_not_overbought = rsi < 78\n    is_sentiment_permissive_for_buy = sentiment_score > -3.0\n    is_sufficient_volatility = short_atr > (long_atr * 0.6) \n    is_price_in_bollinger_band = current_price > lower_band and current_price < upper_band\n    is_price_in_keltner_channel = current_price > keltner_lower_band and current_price < keltner_upper_band\n    is_kst_signal = kst_signal > 0\n\n    if is_primary_uptrend and is_momentum_confirming_up and is_not_overbought and is_sentiment_permissive_for_buy and is_sufficient_volatility and is_price_in_bollinger_band and is_price_in_keltner_channel and stochastic_oscillator > 20 and is_kst_signal:\n        return "BUY"\n\n    return "HOLD"	6b603169f12c52dcb6d9faec079b48b4927e63deadd9ba9070916f228774b250	To optimize the active code, I introduced the Ichimoku Cloud indicator, which provides a comprehensive view of the market's trend and momentum. I also updated the sentiment-keyword matching to utilize weightings and negative negation filters. Additionally, I dynamically scaled indicators based on price history 